// Rotary Encoder Control
// Turning the knob raises/lowers LED brightness; clicking it toggles on/off.

const int CLK_PIN = 2;
const int DT_PIN = 3;
const int SW_PIN = 4;
const int LED_PIN = 9;

int brightness = 128;
int lastClkState;
bool ledOn = true;
bool lastButtonReading = HIGH;

void setup() {
  pinMode(CLK_PIN, INPUT);
  pinMode(DT_PIN, INPUT);
  pinMode(SW_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);

  lastClkState = digitalRead(CLK_PIN);
  applyBrightness();
}

void loop() {
  // --- Rotation ---
  int currentClkState = digitalRead(CLK_PIN);
  if (currentClkState != lastClkState) { // CLK just changed — a detent has moved
    if (digitalRead(DT_PIN) != currentClkState) {
      brightness = min(255, brightness + 8); // clockwise
    } else {
      brightness = max(0, brightness - 8);   // counter-clockwise
    }
    applyBrightness();
  }
  lastClkState = currentClkState;

  // --- Push button (toggle on/off) ---
  bool currentButtonReading = digitalRead(SW_PIN);
  if (currentButtonReading == LOW && lastButtonReading == HIGH) {
    ledOn = !ledOn;
    applyBrightness();
    delay(30); // debounce
  }
  lastButtonReading = currentButtonReading;
}

void applyBrightness() {
  analogWrite(LED_PIN, ledOn ? brightness : 0);
}
